<script>
document.addEventListener('DOMContentLoaded',function(){var input=document.getElementById('chiefSearch'),rows=[].slice.call(document.querySelectorAll('#chiefRows tr[data-search]')),empty=document.getElementById('chiefNoResults');if(input){input.addEventListener('input',function(){var term=input.value.toLowerCase().trim(),visible=0;rows.forEach(function(row){var show=row.dataset.search.indexOf(term)!==-1;row.hidden=!show;if(show)visible++});empty.hidden=visible!==0})}document.querySelectorAll('[data-center-picker]').forEach(function(picker){var form=picker.closest('form'),mfi=form.querySelector('select[name="mfi"]'),search=picker.querySelector('input[type="search"]'),options=[].slice.call(picker.querySelectorAll('[data-center-option]')),empty=picker.querySelector('.chief-picker-empty'),count=form.querySelector('[data-count-for]'),preview=form.querySelector('[data-selected-preview]');function refresh(){var selected=(mfi.value||'').trim().toUpperCase(),term=(search.value||'').trim().toLowerCase(),visible=0,names=[];options.forEach(function(option){var checkbox=option.querySelector('input'),belongsToSelectedMfi=!!selected&&option.dataset.mfi===selected,show=belongsToSelectedMfi&&(!term||option.dataset.name.indexOf(term)!==-1);option.hidden=!show;if(!belongsToSelectedMfi&&checkbox.checked){checkbox.checked=false;option.setAttribute('aria-checked','false')}if(show)visible++;if(checkbox.checked)names.push(option.dataset.label)});empty.hidden=visible!==0;empty.textContent=selected?'No centers match this MFI or search.':'Select an MFI to view its centers.';count.textContent=names.length?names.length+' center'+(names.length===1?'':'s')+' selected':'Choose one or more';preview.hidden=!names.length;if(names.length)preview.textContent='Selected centers: '+names.join(', ')}function toggle(option){if(option.dataset.disabled==='true')return;var checkbox=option.querySelector('input');checkbox.checked=!checkbox.checked;option.setAttribute('aria-checked',checkbox.checked?'true':'false');refresh()}mfi.addEventListener('change',refresh);search.addEventListener('input',refresh);options.forEach(function(option){option.addEventListener('click',function(){toggle(option)});option.addEventListener('keydown',function(event){if(event.key===' '||event.key==='Enter'){event.preventDefault();toggle(option)}})});form.addEventListener('submit',function(event){if(!options.some(function(option){return option.querySelector('input').checked})){event.preventDefault();picker.classList.add('chief-picker-invalid');search.focus();count.textContent='Select at least one center';return}picker.classList.remove('chief-picker-invalid')});refresh()})});
</script>
<script>
document.addEventListener('DOMContentLoaded',function(){function options(select,items,placeholder,selected){select.innerHTML='';var first=document.createElement('option');first.value='';first.textContent=placeholder;select.appendChild(first);items.forEach(function(item){var option=document.createElement('option');option.value=item.name;option.textContent=item.name;option.selected=item.name===selected;select.appendChild(option)});select.disabled=false}function loadLocation(form){if(form.dataset.locationReady)return;form.dataset.locationReady='true';var region=form.querySelector('.chief-location-region'),province=form.querySelector('.chief-location-province'),city=form.querySelector('.chief-location-city'),barangay=form.querySelector('.chief-location-barangay');var desired={region:region.dataset.current||'',province:province.dataset.current||'',city:city.dataset.current||'',barangay:barangay.dataset.current||''};function reset(select,message){select.disabled=true;select.innerHTML='<option value="">'+message+'</option>'}function request(url){return fetch(url).then(function(response){if(!response.ok)throw new Error('Location service unavailable');return response.json()})}function loadBarangays(){var value=city.value;reset(barangay,'Loading barangays…');if(!value){reset(barangay,'Select city first');return}request('/api/cities/'+encodeURIComponent(value)+'/barangays').then(function(items){options(barangay,items,'Select barangay',desired.barangay);desired.barangay='';barangay.dispatchEvent(new Event('change',{bubbles:true}))}).catch(function(){reset(barangay,'Unable to load barangays')})}function loadCities(){var value=province.value;reset(city,'Loading cities…');reset(barangay,'Select city first');if(!value){reset(city,'Select province first');return}request('/api/provinces/'+encodeURIComponent(value)+'/cities').then(function(items){options(city,items,'Select city / municipality',desired.city);desired.city='';loadBarangays()}).catch(function(){reset(city,'Unable to load cities')})}function loadProvinces(){var value=region.value;reset(province,'Loading provinces…');reset(city,'Select province first');reset(barangay,'Select city first');if(!value){reset(province,'Select region first');return}request('/api/regions/'+encodeURIComponent(value)+'/provinces').then(function(items){options(province,items,'Select province',desired.province);desired.province='';loadCities()}).catch(function(){reset(province,'Unable to load provinces')})}region.addEventListener('change',function(){desired.province='';desired.city='';desired.barangay='';loadProvinces()});province.addEventListener('change',function(){desired.city='';desired.barangay='';loadCities()});city.addEventListener('change',function(){desired.barangay='';loadBarangays()});request('/api/regions').then(function(items){options(region,items,'Select region',desired.region);desired.region='';loadProvinces()}).catch(function(){reset(region,'Unable to load regions')})}document.querySelectorAll('.chief-modal').forEach(function(modal){modal.addEventListener('shown.bs.modal',function(){var form=modal.querySelector('form');if(form)loadLocation(form)})})});
</script>
